package webui

const stylesClientAccessPage = `/* Client access workspace v51: dedicated, filterable exports outside node service cards. */
.service-client-access{min-height:42px;display:flex;align-items:center;justify-content:space-between;gap:10px;border-top:1px solid color-mix(in srgb,var(--green) 22%,var(--line));padding:7px 14px;background:color-mix(in srgb,var(--green-soft) 34%,var(--surface));color:var(--ink-2)}.service-client-access:hover{background:color-mix(in srgb,var(--green-soft) 62%,var(--surface));color:var(--green)}.service-client-access span{min-width:0}.service-client-access b,.service-client-access small{display:block}.service-client-access b{font-size:9px}.service-client-access small{margin-top:1px;overflow:hidden;color:var(--muted);font-size:8px;text-overflow:ellipsis;white-space:nowrap}.service-client-access strong{flex:0 0 auto;color:var(--green);font-size:8px}.service-client-access i{margin-left:3px;font-style:normal}
.client-access-workspace{display:grid;gap:14px}.client-access-hero{min-height:132px;display:flex;align-items:center;justify-content:space-between;gap:30px;padding:24px 26px;border:1px solid color-mix(in srgb,var(--accent) 18%,var(--line));border-radius:16px;background:linear-gradient(135deg,var(--surface),color-mix(in srgb,var(--accent-soft) 58%,var(--surface)));box-shadow:var(--shadow)}.client-access-hero>div:first-child{min-width:0}.client-access-hero h1{margin-top:3px;font-size:26px;letter-spacing:-.035em}.client-access-hero p:last-child{max-width:680px;margin-top:7px;color:var(--muted);font-size:11px;line-height:1.7}.client-access-summary{display:grid;grid-template-columns:repeat(2,minmax(118px,1fr));gap:8px;margin:0}.client-access-summary div{min-width:118px;padding:14px 16px;border:1px solid color-mix(in srgb,var(--accent) 18%,var(--line));border-radius:12px;background:color-mix(in srgb,var(--surface) 84%,transparent)}.client-access-summary dt{color:var(--muted);font-size:9px;font-weight:700}.client-access-summary dd{margin:4px 0 0;color:var(--accent);font-size:23px;font-weight:800}
.client-access-filter-panel{display:grid;gap:12px;padding:16px 18px;border:1px solid var(--line);border-radius:14px;background:var(--surface);box-shadow:var(--shadow)}.client-access-search{display:grid;grid-template-columns:minmax(260px,1fr) auto auto;align-items:end;gap:8px}.client-access-search label{display:grid;gap:5px;color:var(--muted);font-size:9px;font-weight:750}.client-access-search input{width:100%}.client-access-filter-row{display:grid;grid-template-columns:52px minmax(0,1fr);align-items:start;gap:10px;padding-top:11px;border-top:1px solid var(--line)}.client-access-filter-row>span{padding-top:7px;color:var(--muted);font-size:9px;font-weight:750}.client-access-filter-row nav{display:flex;flex-wrap:wrap;gap:6px}.client-access-filter-row a{min-height:30px;display:inline-flex;align-items:center;border:1px solid var(--line);border-radius:8px;padding:5px 10px;background:var(--surface-2);color:var(--muted);font-size:9px;font-weight:700}.client-access-filter-row a:hover{border-color:var(--accent);color:var(--accent)}.client-access-filter-row a.active{border-color:color-mix(in srgb,var(--accent) 54%,var(--line));background:var(--accent-soft);color:var(--accent);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--accent) 10%,transparent)}
.client-access-results-head{display:flex;align-items:center;justify-content:space-between;padding:2px 3px;color:var(--muted);font-size:10px}.client-access-results-head strong{color:var(--ink-2);font-size:10px}.client-access-entry-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,480px),1fr));align-items:start;gap:14px}.client-access-entry{min-width:0;border:1px solid var(--line);border-radius:15px;background:var(--surface);box-shadow:var(--shadow);overflow:hidden}.client-access-entry-head{min-height:72px;display:flex;align-items:center;justify-content:space-between;gap:16px;padding:13px 16px;border-bottom:1px solid var(--line)}.client-access-node{min-width:0;display:flex;align-items:center;gap:10px}.client-access-node>.node-avatar{width:36px;height:36px;flex:0 0 36px}.client-access-node strong,.client-access-node small{display:block}.client-access-node strong{overflow:hidden;font-size:13px;text-overflow:ellipsis;white-space:nowrap}.client-access-node small{margin-top:2px;color:var(--muted);font-size:9px}.client-access-engine{display:flex;align-items:center;gap:7px;flex:0 0 auto}.engine-badge.ss-rust{color:#b96b0a}.client-access-entry-meta{display:grid;grid-template-columns:minmax(120px,1fr) minmax(90px,.7fr) auto;align-items:center;gap:12px;padding:10px 16px;border-bottom:1px solid var(--line);background:var(--surface-2)}.client-access-entry-meta>span{min-width:0}.client-access-entry-meta small,.client-access-entry-meta code,.client-access-entry-meta strong{display:block}.client-access-entry-meta small{color:var(--muted);font-size:8px}.client-access-entry-meta code,.client-access-entry-meta strong{margin-top:2px;overflow:hidden;color:var(--ink-2);font-size:9px;text-overflow:ellipsis;white-space:nowrap}.client-access-entry-meta>a{color:var(--accent);font-size:9px;font-weight:750}.client-access-profile-grid{display:grid;gap:10px;padding:14px;background:color-mix(in srgb,var(--surface-2) 68%,var(--surface))}.client-access-entry .client-profile-card{padding:14px;border-radius:11px}.client-access-entry .client-profile-card>header{align-items:center;margin-bottom:10px}.client-access-entry .client-profile-card>header b{font-size:12px}.client-access-entry .client-profile-card>header small{margin-top:2px;font-size:9px}.client-access-entry .client-share-control{display:flex}.client-access-entry .client-share-control input{width:100%;height:40px;font-size:10px}.client-access-entry .client-share-control button{min-width:52px}.client-access-entry .client-parameter-menu{margin-top:10px;border-radius:9px}.client-access-entry .client-parameter-menu>summary{min-height:38px;padding:7px 10px;font-size:9px}.client-access-entry .client-parameters{grid-template-columns:repeat(3,minmax(0,1fr));margin:0;border:0;border-radius:0}.client-access-entry .client-parameters>div{padding:10px}.client-access-entry .client-parameters code{font-size:9px}.client-access-entry .client-parameters .secret-value-control{display:flex}.client-access-empty-state{grid-column:1/-1;min-height:330px;display:flex;align-items:center;justify-content:center;flex-direction:column;padding:34px;border:1px dashed var(--line-2);border-radius:15px;background:var(--surface);text-align:center}.client-access-empty-state>span{width:52px;height:52px;display:grid;place-items:center;border-radius:15px;background:var(--accent-soft);color:var(--accent);font-size:25px}.client-access-empty-state h2{margin-top:14px;font-size:17px}.client-access-empty-state p{max-width:520px;margin-top:7px;color:var(--muted);font-size:10px;line-height:1.7}.client-access-empty-state .button{margin-top:16px}
@media(max-width:1280px){.client-access-entry-grid{grid-template-columns:1fr}.client-access-hero{align-items:flex-start}.client-access-summary{flex:0 0 auto}}
@media(max-width:820px){.client-access-workspace{gap:10px}.client-access-hero{min-height:0;align-items:stretch;flex-direction:column;gap:16px;padding:18px;border-radius:14px}.client-access-hero h1{font-size:23px}.client-access-summary{grid-template-columns:1fr 1fr}.client-access-summary div{min-width:0;padding:11px 12px}.client-access-filter-panel{padding:13px}.client-access-search{grid-template-columns:1fr}.client-access-search .button{width:100%}.client-access-filter-row{grid-template-columns:1fr;gap:6px}.client-access-filter-row>span{padding-top:0}.client-access-filter-row nav{flex-wrap:nowrap;overflow-x:auto;padding-bottom:2px}.client-access-filter-row a{min-width:max-content}.client-access-entry-head{align-items:flex-start;flex-direction:column}.client-access-engine{width:100%;justify-content:space-between}.client-access-entry-meta{grid-template-columns:1fr 1fr}.client-access-entry-meta>a{grid-column:1/-1}.client-access-profile-grid{padding:10px}.client-access-entry .client-profile-card{padding:11px}.client-access-entry .client-share-control{flex-wrap:wrap}.client-access-entry .client-share-control input{flex-basis:100%;border-radius:7px}.client-access-entry .client-share-control button{min-height:40px;flex:1;border-top:0}.client-access-entry .client-share-control button:first-of-type{border-left:1px solid var(--line-2);border-radius:7px 0 0 7px}.client-access-entry .client-parameters{grid-template-columns:1fr}.page-client-access .context-sidebar{display:none}}
@media(max-width:820px){.page-client-access .dock-nav a.active{color:var(--accent)}}
`
